        MyMenu,
        Content,
        Notice
    },
    data(){
        return {
            isCollapse:false,
            drawer: false,
        }
    },
    methods:{
        changeCollapse(){
            this.isCollapse = !this.isCollapse;
        } ,
        changeDrawer(){
            this.drawer = !this.drawer;
        }
    }
}
</script>

